strategy_source:
function (ctx, params) 
{
    targets <- ctx$hold()
    sma <- ctx$feature("AAA", "sma_3")
    targets["AAA"] <- if (!is.na(sma) && ctx$close("AAA") > sma) 
        params$qty
    else 0
    if (!is.null(ctx$pulse_seed) && (ctx$pulse_seed%%2L) == 0L) 
        targets["BBB"] <- params$qty_b
    targets
}

